-- APPLIED RECEIPT: eight organiser-supplied Wednesday 18 November 2026 results.
-- Applied with explicit organiser approval; production transaction 1817. DO NOT RERUN.
-- No fixture, team, preference, permission or existing-result changes.
BEGIN;
SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='30s';
LOCK TABLE public.fixtures,public.result_versions,public.teams,public.competition_seasons IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE nov18_fixtures_before ON COMMIT DROP AS SELECT * FROM public.fixtures;
CREATE TEMP TABLE nov18_results_before ON COMMIT DROP AS SELECT * FROM public.result_versions;
CREATE TEMP TABLE nov18_teams_before ON COMMIT DROP AS SELECT * FROM public.teams;
CREATE TEMP TABLE nov18_audit_before ON COMMIT DROP AS SELECT * FROM public.admin_audit_log;
CREATE TEMP TABLE nov18_plan ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id": "b24cd826-bfbe-4f0e-b8d0-5312409b8d76", "home_team_id": "bf6a7c6e-83e0-4d6d-8354-9a89ab679eb3", "away_team_id": "3a2cbf2d-326d-4a3b-bd94-56ac4f46a999", "kickoff_time": "19:00:00", "court": 1, "schedule_version": 4, "updated_at": "2026-11-11T12:56:55.882294+00:00", "home": "Dream Team", "away": "Kawsar FC", "home_score": 4, "away_score": 6, "forfeit_side": null}, {"id": "81114ca1-4f2c-4e0e-8173-8d21ad48bcc1", "home_team_id": "8902231b-a7f3-474b-96da-c8b3ac09c74b", "away_team_id": "c9f73f23-1e6c-42df-a7fa-9a7953d9cb75", "kickoff_time": "19:00:00", "court": 2, "schedule_version": 8, "updated_at": "2026-11-11T12:56:55.882294+00:00", "home": "Pops", "away": "Buckle City", "home_score": 9, "away_score": 2, "forfeit_side": null}, {"id": "cc5fe049-d2a1-4ebb-9878-d31da27e1116", "home_team_id": "2c8b11cb-0809-475a-a9e8-d39834c41ccb", "away_team_id": "a4eb0d33-ec37-42c2-bb83-b25ac1f046b5", "kickoff_time": "19:40:00", "court": 1, "schedule_version": 4, "updated_at": "2026-10-31T08:45:07.945244+00:00", "home": "Ibiza", "away": "MTS FC", "home_score": 11, "away_score": 2, "forfeit_side": null}, {"id": "de483476-c861-460f-bc37-83ae570f9f7c", "home_team_id": "b7102a75-a3ad-488c-b16e-f6da36e7f7ba", "away_team_id": "435af587-f6ea-5030-a097-94ad466481c2", "kickoff_time": "19:40:00", "court": 2, "schedule_version": 10, "updated_at": "2026-11-10T12:15:57.93124+00:00", "home": "AFG", "away": "Xaywan", "home_score": 0, "away_score": 5, "forfeit_side": "home"}, {"id": "863de226-72b1-40ec-ac5c-ed24283b3b97", "home_team_id": "8f0b3cd6-a819-411e-b08c-b57a3c9367fe", "away_team_id": "b4b3cb39-f59c-4ea3-b176-8e637bfb7e8b", "kickoff_time": "20:20:00", "court": 1, "schedule_version": 6, "updated_at": "2026-10-31T08:45:07.945244+00:00", "home": "Rinnai", "away": "Ghazni United", "home_score": 2, "away_score": 10, "forfeit_side": null}, {"id": "645f5ed4-3e62-44b9-afc9-e8db4bb80ed1", "home_team_id": "5b5d3141-f8b7-481e-9e97-9407d8f224b9", "away_team_id": "b3be09fa-1f9e-4501-be80-ae0346804d31", "kickoff_time": "20:20:00", "court": 2, "schedule_version": 5, "updated_at": "2026-11-12T20:49:12.188004+00:00", "home": "Kuq E Zi", "away": "Goldlink Up", "home_score": 6, "away_score": 7, "forfeit_side": null}, {"id": "8d2401a8-c90d-48bd-be7f-8d7cee019e16", "home_team_id": "99d1aedc-409b-4495-b32c-c874ec5958e0", "away_team_id": "bafe147f-c3ac-4285-8159-f8e13a06e067", "kickoff_time": "21:00:00", "court": 1, "schedule_version": 5, "updated_at": "2026-11-12T20:49:12.188004+00:00", "home": "King ADL", "away": "Umoja Stars", "home_score": 0, "away_score": 5, "forfeit_side": null}, {"id": "d63c58b8-9de9-4c6c-b7bd-ef11be4591cb", "home_team_id": "92b8f805-41b1-446a-b843-6f7cc7083e90", "away_team_id": "a7306808-977f-496c-8f6c-3141529ca76c", "kickoff_time": "21:00:00", "court": 2, "schedule_version": 6, "updated_at": "2026-11-10T12:15:57.93124+00:00", "home": "Misfits", "away": "Wildcats", "home_score": 7, "away_score": 11, "forfeit_side": null}]'::jsonb) AS x(id uuid,home_team_id uuid,away_team_id uuid,kickoff_time time,court integer,schedule_version bigint,updated_at timestamptz,home text,away text,home_score integer,away_score integer,forfeit_side text);
DO $$BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.competition_seasons WHERE id='be008d39-f175-45c1-a232-2148d84b1cf9' AND lifecycle='active' AND publication_state='published') THEN RAISE EXCEPTION 'Edition is not active';END IF;
 IF (SELECT count(*) FROM public.fixtures WHERE competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' AND match_date='2026-11-18' AND publication_state='published' AND schedule_status='scheduled')<>8 THEN RAISE EXCEPTION 'Unexpected round size';END IF;
 IF EXISTS(SELECT 1 FROM nov18_plan p LEFT JOIN public.fixtures f USING(id) LEFT JOIN public.teams h ON h.id=f.home_team_id LEFT JOIN public.teams a ON a.id=f.away_team_id WHERE f.id IS NULL OR f.competition_season_id<>'be008d39-f175-45c1-a232-2148d84b1cf9' OR f.round_number<>4 OR f.match_date<>'2026-11-18' OR f.stage<>'regular_season' OR f.publication_state<>'published' OR f.schedule_status<>'scheduled' OR row(f.home_team_id,f.away_team_id,f.kickoff_time,f.court,f.schedule_version,f.updated_at,h.name,a.name) IS DISTINCT FROM row(p.home_team_id,p.away_team_id,p.kickoff_time,p.court,p.schedule_version,p.updated_at,p.home,p.away)) THEN RAISE EXCEPTION 'Fixture baseline changed';END IF;
 IF EXISTS(SELECT 1 FROM public.result_versions WHERE fixture_id IN(SELECT id FROM nov18_plan)) THEN RAISE EXCEPTION 'Result work already exists; inspect before retrying';END IF;
END $$;
INSERT INTO public.result_versions(fixture_id,revision,status,home_score,away_score,forfeit_side)
SELECT id,1,'published',home_score,away_score,forfeit_side FROM nov18_plan;
DO $$BEGIN
 IF EXISTS(SELECT 1 FROM nov18_fixtures_before b FULL JOIN public.fixtures f USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(f)) THEN RAISE EXCEPTION 'Fixtures changed';END IF;
 IF EXISTS(SELECT 1 FROM nov18_teams_before b FULL JOIN public.teams t USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Team profiles changed';END IF;
 IF EXISTS(SELECT 1 FROM nov18_results_before b LEFT JOIN public.result_versions r USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(r)) THEN RAISE EXCEPTION 'Existing results changed';END IF;
 IF (SELECT count(*) FROM public.result_versions)<>(SELECT count(*)+8 FROM nov18_results_before) OR (SELECT count(*) FROM nov18_plan p JOIN public.result_versions r ON r.fixture_id=p.id WHERE r.status='published' AND r.revision=1 AND r.home_score=p.home_score AND r.away_score=p.away_score AND r.forfeit_side IS NOT DISTINCT FROM p.forfeit_side AND r.published_at IS NOT NULL)<>8 THEN RAISE EXCEPTION 'Result verification failed';END IF;
 IF EXISTS(SELECT 1 FROM nov18_audit_before b LEFT JOIN public.admin_audit_log a USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(a)) THEN RAISE EXCEPTION 'Existing audit changed';END IF;
END $$;
SELECT txid_current() AS transaction_id,p.home,p.home_score,p.away_score,p.away FROM nov18_plan p ORDER BY p.kickoff_time,p.court;
COMMIT;
